import { expect, it } from 'vitest'
import { verifyWebhookSignature } from './signature'

// Published Svix manual-verification test vector, not a signature generated by this code.
const body = '{"event_type":"ping","data":{"success":true}}'
const secret = 'whsec_plJ3nmyCDGBKInavdOK15jsl'
const headers = new Headers({
  'svix-id': 'msg_loFOjxBNrRLzqYUf', 'svix-timestamp': '1731705121',
  'svix-signature': 'v1,rAvfW3dJ/X/qxhsaXPOyyCGmRKsaKWcsNccKXlIktD0=',
})
const now = 1731705121000

it('accepts the published Svix HMAC vector', () => {
  expect(verifyWebhookSignature({ body, headers, secret, now })).toBe(true)
})
it('accepts a valid v1 signature during signature rotation', () => {
  const rotated = new Headers(headers)
  rotated.set('svix-signature', `v2,ignored v1,invalid ${headers.get('svix-signature')}`)
  expect(verifyWebhookSignature({ body, headers: rotated, secret, now })).toBe(true)
})
it.each([['body', 'changed'], ['svix-id', 'different'], ['svix-timestamp', '1731705122'], ['svix-signature', 'v1,broken']])('rejects tampered %s', (field, value) => {
  const changed = new Headers(headers)
  if (field !== 'body') changed.set(field, value)
  expect(verifyWebhookSignature({ body: field === 'body' ? value : body, headers: changed, secret, now })).toBe(false)
})
it.each([-301_000, 301_000])('rejects timestamps outside the replay window (%i ms)', offset => {
  expect(verifyWebhookSignature({ body, headers, secret, now: now + offset })).toBe(false)
})
it.each(['', 'not-a-secret', 'whsec_%%%%'])('fails closed on invalid secret configuration', invalidSecret => {
  expect(verifyWebhookSignature({ body, headers, secret: invalidSecret, now })).toBe(false)
})
it('rejects missing headers', () => {
  expect(verifyWebhookSignature({ body, headers: new Headers(), secret, now })).toBe(false)
})
